import assert from "node:assert/strict";
import { test } from "node:test";
import { createTask, updateTask } from "../src/store.js";

test("PATCH preserves created_at", () => {
	const task = createTask("write docs", new Date("2026-03-01T10:00:00Z"));
	const updated = updateTask(task.id, { status: "done" }, new Date("2026-03-02T09:00:00Z"));
	assert.equal(updated.created_at, "2026-03-01T10:00:00Z");
});

