test("writes use UTC timestamps without milliseconds across reads", () => {
	const task = createTask("timestamp regression", new Date("2026-03-01T12:00:00.987+02:00"));
	assert.equal(task.created_at, "2026-03-01T10:00:00Z");
	assert.equal(task.updated_at, task.created_at);
	const updated = updateTask(task.id, { status: "done" }, new Date("2026-03-02T09:00:00.456Z"));
	assert.equal(updated.updated_at, "2026-03-02T09:00:00Z");
	assert.equal(updated.created_at, task.created_at);
	assert.deepEqual(getTask(task.id), updated);
	assert.deepEqual(listTasks().find(({ id }) => id === task.id), updated);
});

test("serialization preserves stored timestamps and returns a copy", () => {
	const task = { created_at: "2026-03-01T10:00:00Z", updated_at: "2026-03-02T09:00:00Z", deleted_at: null };
	const serialized = serializeTask(task);
	assert.deepEqual(serialized, task);
	assert.notEqual(serialized, task);
});

