const tasks = new Map();
const serializedTasks = new Map();
const CACHE_LIMIT = 500;

function cacheKey(task) {
	return JSON.stringify([task.id, task.updated_at]);
}

export function serializeTask(task) {
	const key = cacheKey(task);
	const cached = serializedTasks.get(key) ?? { ...task };
	serializedTasks.delete(key);
	serializedTasks.set(key, cached);
	if (serializedTasks.size > CACHE_LIMIT) {
		serializedTasks.delete(serializedTasks.keys().next().value);
	}
	return { ...cached };
}

