	const task = createTask("same second", now);
	updateTask(task.id, { status: "done" }, now);
	assert.equal(getTask(task.id).status, "done");
	const returned = getTask(task.id);
	returned.status = "open";
	assert.equal(getTask(task.id).status, "done");
