import { createTask, getTask, listTasks, updateTask } from "../store.js";

function error(status, code, message) {
	return { status, body: { error: { code, message } } };
}

function list(url) {
	const raw = url.searchParams.get("limit") ?? "25";
	const limit = Number(raw);
	if (!/^\d+$/.test(raw) || !Number.isInteger(limit) || limit < 1 || limit > 100) {
		return error(400, "invalid_limit", "limit must be an integer between 1 and 100");
	}
	return { status: 200, body: { items: listTasks().slice(0, limit) } };
}

function writeTask(method, id, body) {
	let data;
	try {
		data = JSON.parse(body || "{}");
	} catch {
		return error(400, "invalid_json", "request body must be valid JSON");
	}
	if (!data || typeof data !== "object" || Array.isArray(data)) {
		return error(400, "invalid_body", "request body must be a JSON object");
	}
	if (method === "POST") {
		if (typeof data.title !== "string" || !data.title.trim()) {
			return error(400, "invalid_title", "title required");
		}
		return { status: 201, body: createTask(data.title) };
	}
	const task = updateTask(id, data);
	return task ? { status: 200, body: task } : error(404, "not_found", "not found");
}

export function handle(method, url, body) {
	const parts = url.pathname.split("/").filter(Boolean);
	if (parts[0] !== "tasks" || parts.length > 2) {
		return error(404, "not_found", "not found");
	}
	if (method === "GET" && parts.length === 1) return list(url);
	if ((method === "POST" && parts.length === 1) || method === "PATCH") {
		return writeTask(method, parts[1], body);
	}
	if (method === "GET") {
		const task = getTask(parts[1]);
		return task ? { status: 200, body: task } : error(404, "not_found", "not found");
	}
	return error(405, "method_not_allowed", "method not allowed");
}

import assert from "node:assert/strict";
import { test } from "node:test";
import { handle } from "../src/routes/tasks.js";

function request(method, path, body) {
	return handle(method, new URL(path, "http://localhost"), body);
}

const cases = [
	["GET", "/other", undefined, 404, "not_found"],
	["GET", "/tasks/missing", undefined, 404, "not_found"],
	["GET", "/tasks/a/b", undefined, 404, "not_found"],
	["PATCH", "/tasks/missing", "{}", 404, "not_found"],
	["DELETE", "/tasks", undefined, 405, "method_not_allowed"],
	["POST", "/tasks", "{}", 400, "invalid_title"],
	["POST", "/tasks", '{"title":" "}', 400, "invalid_title"],
	["POST", "/tasks", '{"title":42}', 400, "invalid_title"],
];
for (const method of ["POST", "PATCH"]) {
	const path = method === "POST" ? "/tasks" : "/tasks/missing";
	cases.push([method, path, "{", 400, "invalid_json"]);
	for (const body of ["null", "[]", "42", '"text"']) {
		cases.push([method, path, body, 400, "invalid_body"]);
	}
}
for (const limit of ["", "0", "-1", "101", "1.5", "abc", "Infinity", "1e2"]) {
	cases.push(["GET", `/tasks?limit=${limit}`, undefined, 400, "invalid_limit"]);
}
for (const [method, path, body, status, code] of cases) {
	test(`${method} ${path} ${body ?? ""} returns ${code} envelope`, () => {
		const result = request(method, path, body);
		assert.equal(result.status, status);
		assert.deepEqual(Object.keys(result.body), ["error"]);
		assert.deepEqual(Object.keys(result.body.error).sort(), ["code", "message"]);
		assert.equal(result.body.error.code, code);
		assert.equal(typeof result.body.error.message, "string");
		assert.ok(result.body.error.message.length > 0);
	});
}

test("successful create, get, patch and list retain their response shapes", () => {
	const created = request("POST", "/tasks", '{"title":"route regression"}');
	assert.equal(created.status, 201);
	const path = `/tasks/${created.body.id}`;
	assert.deepEqual(request("GET", path).body, created.body);
	const patched = request("PATCH", path, '{"status":"done"}');
	assert.equal(patched.status, 200);
	assert.equal(patched.body.status, "done");
	for (const query of ["", "?limit=1", "?limit=100"]) {
		const listed = request("GET", `/tasks${query}`);
		assert.equal(listed.status, 200);
		assert.ok(Array.isArray(listed.body.items));
	}
});

