export function deleteTask(id, now = new Date()) {
	const task = tasks.get(id);
	if (!task || task.deleted_at) return undefined;
	serializedTasks.delete(cacheKey(task));
	const stamp = timestamp(now);
	Object.assign(task, { deleted_at: stamp, updated_at: stamp });
	return serializeTask(task);
}

export function listTasks() {
	return [...tasks.values()].filter((task) => !task.deleted_at).map(serializeTask);
}

