	const task = request("POST", "/tasks", JSON.stringify({ title: "patch validation" })).body;
	const path = `/tasks/${task.id}`;
	const invalid = [
		... ["id", "created_at", "updated_at", "deleted_at", "extra", "__proto__"]
			.map((key) => [Object.fromEntries([[key, "replacement"]]), "invalid_field"]),
		... ["", " ", null, 42, {}, []].map((title) => [{ title }, "invalid_title"]),
		... ["pending", "OPEN", "", null, 42, {}, []]
			.map((status) => [{ status }, "invalid_status"]),
	];
	for (const [changes, code] of invalid) {
		const result = request("PATCH", path, JSON.stringify({ title: "must not persist", ...changes }));
		assert.equal(result.status, 400);
		assert.equal(result.body.error.code, code);
		assert.equal(typeof result.body.error.message, "string");
